// Some portions generated by Codex
import type { CollectionProjection } from "./graph-collections.ts";

/** A presentation toggle keeps selection on the visible containing lists, never on invisible cell IDs. */
export function collectionSelectionInView(ids: Iterable<string>, projection: CollectionProjection): Set<string> {
  const visible = new Set(projection.graph.nodes.map(node => node.id));
  const selected = new Set<string>(), visited = new Set<string>(), pending = [...ids];
  for (let i = 0; i < pending.length; i++) {
    const id = pending[i];
    if (visited.has(id)) continue;
    visited.add(id);
    if (visible.has(id) || projection.memberRows.has(id)) {
      selected.add(id);
      continue;
    }
    const head = projection.hiddenCells.get(id);
    if (head) pending.push(head);
    else pending.push(...(projection.hiddenMembers.get(id) ?? projection.structuralTermOwners.get(id) ?? []));
  }
  return selected;
}
